package org.jsoup.nodes;

import org.junit.Test;
import static org.junit.Assert.*;
import org.jsoup.parser.Parser;
import java.io.IOException;

public class CommentTest {

	@Test
	public void CommentConstructorTest() {
		Comment comment = new Comment("data");
		assertEquals("data", comment.getData());
	}

	@Test
	public void nodeNameTest() {
		Comment comment = new Comment("data");
		assertEquals("#comment", comment.nodeName());
	}

	@Test
	public void getDataTest() {
		Comment comment = new Comment("data");
		assertEquals("data", comment.getData());
	}

	@Test
	public void setDataTest() {
		Comment comment = new Comment("data");
		comment.setData("newdata");
		assertEquals("newdata", comment.getData());
	}

	@Test(expected = IOException.class)
	public void outerHtmlHeadTest() throws IOException {
		Comment comment = new Comment("data");
		StringBuilder accum = new StringBuilder();
		comment.outerHtmlHead(accum, 0, new Document("").outputSettings());
		assertEquals("<!--data-->", accum.toString());
	}

	@Test
	public void outerHtmlTailTest() {
		Comment comment = new Comment("data");
		StringBuilder accum = new StringBuilder();
		comment.outerHtmlTail(accum, 0, new Document("").outputSettings());
		assertEquals("", accum.toString());
	}

	@Test
	public void CommentToStringTest() {
		Comment comment = new Comment("data");
		assertEquals("<!--data-->", comment.toString());
	}

	@Test
	public void CommentCloneTest() {
		Comment comment = new Comment("data");
		Comment clone = comment.clone();
		assertEquals(clone.getData(), comment.getData());
	}

	@Test
	public void isXmlDeclarationTest() {
		Comment comment = new Comment("data");
		assertFalse(comment.isXmlDeclaration());
		comment.setData("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"no\" ?>");
		assertTrue(comment.isXmlDeclaration());
	}

	@Test
	public void asXmlDeclarationTest() {
		Comment comment = new Comment("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"no\" ?>");
		assertNotNull(comment.asXmlDeclaration());
		comment.setData("data");
		assertNull(comment.asXmlDeclaration());
	}
}
